const resolveDefaultProps = <Defaults extends object, Props extends object>(
  defaults: Defaults,
  props: Props
) => {
  const supplied = props as Record<string, unknown>;
  const fallbackEntries = Object.entries(defaults).map(([key, value]) => [
    key,
    supplied[key] === undefined ? value : supplied[key],
  ]);

  return {
    ...defaults,
    ...props,
    ...Object.fromEntries(fallbackEntries),
  } as Defaults & Props;
};

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

interface NativeImageCardData {
  alt: string;
  heading: string;
  href: string;
  src: string;
  subtext: string;
}

const ImageGridEmailShell = ({
  backgroundColor,
  children,
  preview,
  theme,
}: {
  backgroundColor: string;
  children: ReactNode;
  preview: string;
  theme: EmailTheme;
}) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>{preview}</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody backgroundColor={backgroundColor} width={theme.containerWidth}>
      <MjmlWrapper padding="0">{children}</MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

const NativeImageCard = ({
  data,
  headingColor,
  overlay,
  textColor,
  width,
}: {
  data: NativeImageCardData;
  headingColor: string;
  overlay: boolean;
  textColor: string;
  width: number;
}) => (
  <>
    <MjmlImage
      alt={data.alt}
      borderRadius={overlay ? "4px 4px 0 0" : "4px"}
      href={data.href}
      padding="0"
      src={data.src}
      width={`${width}px`}
    />
    {overlay ? (
      <>
        <MjmlText
          backgroundColor="#000001"
          color={headingColor}
          fontFamily={fontFamily}
          fontSize="20px"
          fontWeight="700"
          lineHeight="28px"
          padding="16px 16px 0"
        >
          {data.heading}
        </MjmlText>
        <MjmlText
          backgroundColor="#000001"
          color={textColor}
          fontFamily={fontFamily}
          fontSize="16px"
          lineHeight="24px"
          padding="0 16px 16px"
        >
          {data.subtext}
        </MjmlText>
      </>
    ) : null}
  </>
);

const NativeFeatureImage = ({
  backgroundColor,
  data,
  headingColor,
  overlay,
  padding = "0 24px 24px",
  textColor,
}: {
  backgroundColor: string;
  data: NativeImageCardData;
  headingColor: string;
  overlay: boolean;
  padding?: string;
  textColor: string;
}) => (
  <MjmlSection backgroundColor={backgroundColor} padding={padding}>
